        for (var i = 0; i < tokens.Count; i++)
        {
            var acc = "";
            for (var j = i; j < tokens.Count; j++)
            {
                acc += tokens[j];
                if (acc == clave) { r.Add((i, j - i + 1)); break; }
                if (!clave.StartsWith(acc, StringComparison.Ordinal)) break;
            }
        }
        return r;
    }

